STORY = [('manager', '신디에겐 절대 비밀로 할게요. 걱정 마세요.', "I will keep it an absolute secret from Cindy. Don't worry.", [(817, '절대 비밀로'), (819, '걱정 마세요')], ''), ('manager', '몰래카메라라서 알고 찍히면 티 나고 재미없대.', 'Since it is a hidden camera, they said it looks obvious and unfunny if you know beforehand.', [(824, '알고 찍히면'), (825, '완전 티나고 재미없다고')], ''), ('cindy', '오빠, 리얼 그거 별거 아니야.', 'Listen, reality television is no big deal.', [(828, '오빠'), (829, '리얼 그거 별거 아니야')], ''), ('cindy', '사람들은 자기가 보고 싶은 것만 보고 리얼이라고 생각한다니까.', 'People see only what they want to see and call that reality.', [(830, '사람들은'), (831, '자기가 보고 싶은 것만 보고'), (832, '그거 리얼이라고 생각한다니까')], ''), ('cindy', '그동안 차갑게만 보이던 내 이미지를 친근하게 바꾸려는 거야.', 'I am going to change my cold image into something friendly and approachable.', [(836, '그동안 어렵고 차갑게만 보이던 내 이미지'), (837, '이번에 바꾸려는 거야'), (838, '뭔가 친근하고')], ''), ('cindy', '사람들이 연예인 이름 앞에 별명을 붙였는데 웃기더라고.', "People put nicknames in front of celebrities' names, and it was really funny.", [(841, '사람들이 연예인 이름 앞에 별명을 붙였는데 웃기더라고')], ''), ('cindy', '나도 그런 식의 별명이 생겼으면 좋겠다는 거지.', 'So I hope I get a nickname like that too.', [(844, '그러니까 나도 그런 식의 별명이 생겼으면 좋겠다는 거지')], ''), ('manager', '사자성어처럼 미소천사 신디, 이런 거?', 'Like a four-character phrase, something like Smiling Angel Cindy?', [(845, '사자성어처럼'), (845, '이런 거')], ''), ('cindy', '난 원래 미소천사인데 반대로 가야지. 천년보살 신디 어때?', 'I am already a smiling angel, so we should go the opposite way. How about Saintly Cindy?', [(847, '미소 천사인데'), (848, '반대로 가야지'), (849, '신디')], ''), ('manager', '보살은 화를 안 내잖아.', 'A saint never loses her temper, though.', [(850, '보살은 화를 안 내잖아')], ''), ('ilyong', '이 스프레이로 물 뿌리고 신디가 깨면 까나리카노를 내밀면 돼.', 'Spray water with this bottle, and when Cindy wakes up, hand her this fish-sauce coffee.', [(855, '이 스프레이로 물 뿌리고'), (857, '이 까나리카노를 내밀면 돼')], ''), ('ilyong', '까나리카노를 마시고 뿜는 표정이 웃겨야 되거든.', 'Her expression spitting out the fish-sauce coffee has to be hilarious.', [(859, '까나리카노를 마시고 뿜는 표정이 웃겨야 되거든')], '')]
